    [113] = {
      beijing = 4508,
      dialog = 3,
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      sentence = "No one had ever outright told him, or perhaps they had hinted, but he was in too much of a hurry and had never given it serious consideration.",
