    },
    [114] = {
      beijing = 4508,
      dialog = 3,
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      sentence = "Until someone he couldn't bear to part with appeared in his life, leading him to feelings of discomfort and helplessness.",
