    },
    [116] = {
      beijing = 4508,
      dialog = 3,
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      sentence = "He finally saw the lightless ocean for what it was. That starting point—now long gone—was much too far away from him, and he no longer needed to fear stagnation.",
