    [20] = {
      beijing = 8000,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "I had always had somewhat of a grudge against the lax incompetence of the royal family, but after a torch in the Plum Palace sent the entire dynasty to their demise, I didn't even have anywhere to direct my anger.",
