      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "I picked up the jade pendant by my pillow and gripped down hard on it in my hand — As long as I had this, I knew that I'd find him.",
      next = {25}
    },
    [25] = {
      beijing = 8000,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "But before then, I had to continue dealing with this \"dilettante monarch\" Kiro.",
      next = {26}
    },
    [26] = {
      beijing = 8000,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "After quickly getting myself ready, I tied the jade pendant to my waist. Then I walked up to the table and pulled a booklet from one of the compartments of my makeup case.",
      next = {27}
    },
    [27] = {
      beijing = 8000,
      dhead = 1408,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      sentence = "October 21: I kicked the shuttlecock with him for two games and acted out a shadow puppet show. No clues about Bibliotheca.",
      next = {28}
    },
    [28] = {
      beijing = 8000,
      dhead = 1408,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      sentence = "November 4: Didn't want to approve memorials to the throne. Made up an excuse to go back to the imperial bed chamber and slept a whole day.",
      next = {29}
    },
    [29] = {
      beijing = 8000,
      dhead = 1408,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      sentence = "...Later I discovered he was just lying in bed reading plays. No clues about Bibliotheca.",
      next = {30}
    },
    [30] = {
      beijing = 8000,
      dhead = 1408,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      sentence = "December 15: He dragged me away to eat stew. He had quite the appetite, eating a whole pot of mutton by himself...",
      next = {31}
    },
    [31] = {
      beijing = 8000,
      dhead = 1408,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      sentence = "Still no clues about Bibliotheca.",
      next = {32}
    },
    [32] = {
      beijing = 8000,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "As I looked at the records I'd made about Kiro, I could feel myself break out in a sweat from shame.",
      next = {33}
    },
    [33] = {
      beijing = 8000,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "For the three months that I'd been in the palace, aside from checking in for roll call every morning at the imperial court, Kiro had done nothing all day but bet on cockfights and dog races and other wasteful pursuits, without so much as a care for the proper business of running this country.",
      next = {34}
    },
    [34] = {
      beijing = 8000,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "Meanwhile, the secret letters from my foster father grew more and more dire. In them, he mentioned that there seemed to be a faction in the court at odds with him, and that they were waiting in the wings to strike.",
      next = {35}
    },
    [35] = {
      beijing = 8000,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "Several times he tried to catch the head of this group, but he was given the slip each time.",
      next = {36}
    },
    [36] = {
      beijing = 8000,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "\"No matter the means, you must quickly gain Kiro's trust. If we don't find the location of Bibliotheca soon, I'm afraid the balance of power may shift at any moment.\"",
      next = {37}
    },
    [37] = {
      beijing = 8000,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "These final words of my foster father hit me over the head like a sledgehammer.",
