      beijing = 8000,
      dhead = 1406,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      sentence = "But that treasure trove isn't so easy to find. I've practically combed the whole palace over these three months...",
      next = {39}
    },
    [39] = {
      beijing = 8000,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "The more it troubled me, the more I didn't want to face it. I let out a sigh, then picked up the red bean yogurt from the table and took a sip.",
      next = {40}
    },
    [40] = {
      beijing = 8000,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "The rich and sweet dairy flavor exploded on the tip of my tongue, washing away my bitter worries and actually bringing back the taste of yesterday's mutton stew.",
      next = {41}
    },
    [41] = {
      beijing = 8011,
