      renwu = "npc",
      role1 = 3101000,
      role2 = 3101101,
      role3 = 301201,
      ruchang = -1,
      sentence = "...You can't have the stew without carrots and peppercorns. If you like, we can also add chili peppers sent to court as tribute.",
