    [54] = {
      beijing = 1601,
      bganim = 0,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "First thing this morning, Kiro invited a zither player from among the commoners into the palace to discuss his technique. For a music lover of his intensity, I expected it would be evening before he came out.",
      next = {55}
    },
    [55] = {
      beijing = 1601,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "Since he wouldn't need me by his side, I figured I might as well stroll around.",
      next = {56}
    },
    [56] = {
      beijing = 1601,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "It was now late winter, and the only people on the roads were small groups of patrolling guards. Several ravens flew over the eaves of the buildings, letting out hoarse caws.",
      next = {57}
    },
    [57] = {
      beijing = 1601,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "Ever since the disaster of Plum Palace and Kiro's ascension to the throne, my foster father dismissed most of the staff from the palace on the grounds that \"we could cut expenses by vacating the palace\".",
      next = {58}
    },
    [58] = {
      beijing = 1601,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "So aside from myself as his personal secretary, Kiro only had two or three attendants around him. He was a true and proper \"solitary loner\".",
      next = {59}
    },
    [59] = {
      beijing = 1601,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "For a moment, I suddenly understood why Kiro would drag me off to go have fun every day — Otherwise, palace life would be too lonesome.",
      next = {60}
    },
    [60] = {
      beijing = 1601,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "Once this business was done, I could finally get away from this lifeless place. But what about Kiro? He would have to go on living here, wouldn't he?",
      next = {61}
    },
    [61] = {
      beijing = 1601,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "But then again, the throne is a game of winner takes all, so when my foster father takes the throne, perhaps Kiro might even...",
      next = {62}
    },
    [62] = {
      beijing = 1601,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "I snapped my eyes shut, instinctively trying to block out visions of those blue eyes stained blood red.",
      next = {63}
    },
    [63] = {
      beijing = 1601,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "My mind felt blank, so I just did what I normally did and climbed the man-made mountain, then took out my flute.",
      next = {64}
    },
    [64] = {
      beijing = 1601,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "— In a letter that Brother Evergreen once wrote to me, he said that when he was feeling down, he would play a tune and give his heart over to the music.",
