    [65] = {
      beijing = 1601,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "My foster father had gifted me many musical scores, but for some reason, the score that Brother Evergreen had given me had always been my favorite.",
